## Corrected Implementation

```go
package cache

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type CacheEntry struct {
    Value     interface{}
    ExpiresAt time.Time
    ready     chan struct{} // Signals when loading complete
    err       error         // Store loading error
}

type LoadFunc func(ctx context.Context, key string) (interface{}, error)

type Cache struct {
    data     map[string]*CacheEntry
    mu       sync.RWMutex  // RWMutex for better read concurrency
    ttl      time.Duration
    loader   LoadFunc
    hits     atomic.Int64  // Atomic counters
    misses   atomic.Int64
    loadErrs atomic.Int64
}

func NewCache(ttl time.Duration, loader LoadFunc) *Cache {
    c := &Cache{
        data:   make(map[string]*CacheEntry),
        ttl:    ttl,
        loader: loader,
    }
    go c.cleanupLoop()
    return c
}

func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // Check with read lock first
    c.mu.RLock()
    entry, ok := c.data[key]
    c.mu.RUnlock()

    if ok {
        // Wait for entry to be ready
        select {
        case <-entry.ready:
        case <-ctx.Done():
            return nil, ctx.Err()
        }

        if entry.err != nil {
            return nil, entry.err
        }
        if time.Now().Before(entry.ExpiresAt) {
            c.hits.Add(1)
            return entry.Value, nil
        }
    }

    // Need to load - acquire write lock
    c.mu.Lock()

    // Double-check
    if entry, ok := c.data[key]; ok {
        if time.Now().Before(entry.ExpiresAt) {
            c.mu.Unlock()
            <-entry.ready
            c.hits.Add(1)
            return entry.Value, nil
        }
        // Someone else loading - wait on their channel
        if entry.ready != nil {
            ch := entry.ready
            c.mu.Unlock()
            select {
            case <-ch:
                if entry.err != nil {
                    return nil, entry.err
                }
                return entry.Value, nil
            case <-ctx.Done():
                return nil, ctx.Err()
            }
        }
    }

    // We're the loader - create entry with channel
    entry = &CacheEntry{ready: make(chan struct{})}
    c.data[key] = entry
    c.mu.Unlock()

    c.misses.Add(1)

    // Load outside lock
    value, err := c.loader(ctx, key)

    c.mu.Lock()
    if err != nil {
        c.loadErrs.Add(1)
        entry.err = err
        delete(c.data, key)
    } else {
        entry.Value = value
        entry.ExpiresAt = time.Now().Add(c.ttl)
    }
    close(entry.ready) // Signal all waiters
    c.mu.Unlock()

    if err != nil {
        return nil, err
    }
    return value, nil
}

func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    entry := &CacheEntry{
        Value:     value,
        ExpiresAt: time.Now().Add(c.ttl),
        ready:     make(chan struct{}),
    }
    close(entry.ready)
    c.data[key] = entry
    c.mu.Unlock()
}

func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            value, err := c.Get(ctx, k)
            if err == nil {
                mu.Lock()
                results[k] = value
                mu.Unlock()
            }
        }(key)
    }

    wg.Wait()
    return results
}

func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()

    now := time.Now()
    for key, entry := range c.data {
        select {
        case <-entry.ready:
            if now.After(entry.ExpiresAt) {
                delete(c.data, key)
            }
        default:
            // Still loading, don't delete
        }
    }
}

func (c *Cache) Size() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return len(c.data)
}
```

---

**Key fixes:**
- `sync.RWMutex` for read-heavy workloads
- `atomic.Int64` for stats (no lock contention)
- Channel-based signaling instead of busy-wait (no polling, proper wake-up)
- `sync.WaitGroup` in GetMulti instead of `time.Sleep`
- All map access protected
- Loading errors propagated to waiters

